#!/usr/bin/env python3
"""Render only the fixed, completed run. No fitted rates or extrapolation."""
import hashlib,json,os
os.environ.setdefault("MPLCONFIGDIR", "/tmp/cto001-matplotlib")
os.environ.setdefault("XDG_CACHE_HOME", "/tmp/cto001-cache")
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
BASE=Path(__file__).resolve().parent
r=json.loads((BASE/'results.json').read_text());rows=r['results'];Ms=sorted({x['M'] for x in rows})
def get(M,k):return next(x for x in rows if x['M']==M and x['metric']==k)
fig,axes=plt.subplots(1,2,figsize=(10,4.2),layout='constrained')
for key,label in [('excess_KL_B_Q','Q excess: E KL(B || Q)')]:
    axes[0].errorbar(Ms,[get(m,key)['mean'] for m in Ms],yerr=[1.96*get(m,key)['MC_SE'] for m in Ms],marker='o',capsize=3,label=label)
for key,label in [('cleanTV_B','B: Bayes counts'),('cleanTV_A','A: half gate'),('cleanTV_Q','Q: smoothed half gate')]:
    axes[1].errorbar(Ms,[get(m,key)['mean'] for m in Ms],yerr=[1.96*get(m,key)['MC_SE'] for m in Ms],marker='o',capsize=3,label=label)
for ax in axes:
    ax.set_xscale('log',base=2);ax.set_xticks(Ms,labels=[str(m) for m in Ms]);ax.set_xlabel('Observed transitions M');ax.grid(alpha=.25);ax.legend(fontsize=8)
axes[0].set_ylabel('Clean excess logloss (nats)');axes[1].set_ylabel('Mean clean TV to actual source')
fig.suptitle('Synthetic CTO001 prior diagnostic: 20,000 trajectories per horizon\nError bars: approximate pointwise 95% Monte Carlo intervals',fontsize=11)
fig.savefig(BASE/'synthetic_clean_objective.png',dpi=180)
lines=['# Synthetic clean-objective diagnostic (CTO001)', '', '## Result and scope', '', 'This is a fixed-prior Monte Carlo diagnostic of explicit statistical maps, not neural training and not a worst-case robustness experiment. It uses the accepted CTO001 prior without conditioning on any test certificate. Exactly 20,000 independent simulated trajectories were generated for each of seven predeclared horizons, 140,000 total.', '', 'At M=64 the estimated clean excess of Q over B is 0.0176684 nats (MC SE 0.0004007). At M=4096 it is 0.000820469 nats (MC SE 0.00001119). These are finite-horizon prior averages. We do not fit an asymptotic rate, extrapolate, or infer worst-case behavior from these points.', '', '| M | TV B | TV A | TV Q | excess KL(B||Q) | MC SE excess | gate rejection | weak tail (exact) |', '|---:|---:|---:|---:|---:|---:|---:|---:|']
for m in Ms:
    vals=[get(m,k)['mean'] for k in ['cleanTV_B','cleanTV_A','cleanTV_Q','excess_KL_B_Q']]
    g=get(m,'gate_rejection');w=get(m,'weak_tail');z=(w['mean']-w['exact_weak_tail'])/w['MC_SE']
    lines.append('| '+str(m)+' | '+' | '.join(f'{v:.8f}' for v in vals)+f" | {get(m,'excess_KL_B_Q')['MC_SE']:.8f} | {g['mean']:.6f} | {w['mean']:.6f} ({w['exact_weak_tail']:.6f}) |")
    assert abs(z)<3,('weak-tail sanity check',m,z)
    assert abs(get(m,'expected_logloss_Q')['mean']-get(m,'entropy_B')['mean']-get(m,'excess_KL_B_Q')['mean'])<1e-14
lines+=['', '## Protocol and uncertainty', '', 'config.json and PRE_RUN_HASHES.json were written before the run. They specify horizons, seeds, PCG64 RNG, draw order, and 100 fixed consecutive batches of 200 trajectories. No seeds, horizons, or sample sizes were tuned based on results. Each row parameter is independently uniform and the initial pair independently uniform. The simulator observes M transitions and does not draw the next label. It computes every row count H, first-half row count, and terminal J,C,D, then the true terminal source probability p, Bayes B, oriented half-gate A, and Q.', '', 'The exact conditional quantity KL(B||Q) is averaged, avoiding extra next-label noise. H(B) is the conditional optimal expected logloss. Q conditional expected logloss is H(B)+KL(B||Q). Their population quantities remain Monte Carlo estimates. Logs are natural and complementary logs use log1p. Probability bounds, finiteness, total count, and half-count identities are checked. A logloss is not reported: A can be 0 or 1 while B is strictly interior, so population A logloss is infinite; no arbitrary epsilon is substituted.', '', 'MC SE is the sample standard deviation (ddof=1) of the 100 independent batch means divided by sqrt(100). CSV intervals are mean ±1.96 MC SE, approximate pointwise normal intervals, not finite-sample coverage guarantees or simultaneous confidence bands. Rare-event normal intervals can extend below zero, and zero observed events give a zero estimated SE without implying zero true probability. In particular, gate rejection was not observed in 20,000 draws at M=2048 or 4096; this is not evidence of an identically inactive gate. No paired significance comparison is claimed from marginal intervals.', '', 'The weak-tail fraction is compared with exact 1−(1−2/sqrt(M))^4. All seven deviations are below 1.64 estimated MC SE in magnitude; this is a sanity check, not proof of the simulator. The continuous prior is represented by float64 pseudorandom uniforms in [0,1); endpoint discretization and finite RNG precision are limitations.', '', '## Validation and reproduction', '', 'test_experiment.py is an independent literal list-path/count oracle. It exhausts all 8,188 binary words for M=0..10, verifies count and gate outputs and exact rational posterior extension identities and word-mass normalization. Identical pre-generated transition uniforms are also used to compare the vector simulator against independent literal path simulation at M=0,1,2,3,17,64. Separate cases cover both orientations, J=0, the 512D=J acceptance tie, and a one-count rejection. Metrics are checked against direct conditional cross-entropy, and invalid source probabilities are rejected. tests_red.log records feature-missing NotImplementedError errors before implementation; tests_green.log records the four passing test methods. This is not a full repository suite; no repository-level test configuration was found in the inspected root/top levels.', '', 'Reproduce the sealed run without preparing a new protocol:', '', '    cd v10_research/clean_objective_experiment_20261103', '    python test_experiment.py', '    python experiment.py run', '    python report.py', '', 'Do not run prepare to replay the original protocol: it replaces the timestamp/config hash. run verifies sealed hashes before drawing trajectories. Aggregates and batch means are fully retained; full paths and trajectory-level arrays are not retained, but are reproducible from the declared seeds and code. results.json records Python, NumPy, platform, total runtime and per-horizon runtimes.', '', f"Total simulation/aggregation runtime: {r['runtime_seconds']:.3f} seconds. No external writes, installations, or consolidated manuscript changes were made. The scientific plot uses a logarithmic horizon axis with linear response axes, no fitted line or scaling exponent. Review acceptance is left to the root's independent replay."]
(BASE/'REPORT.md').write_text('\n'.join(lines)+'\n')
print('Rendered report and plot; aggregate identities and weak-tail checks passed.')
